  array(
    'slug' => 'llms-txt-guide',
    'path' => '/blog/llms-txt-guide',
    'parent' => 'blog',
    'type' => 'post',
    'title' => 'llms.txt Explained: Should Your Site Have One?',
    'description' => 'llms.txt is a proposed standard that gives AI systems a curated map of your most useful content. Here is what to include, what to skip, and how it works alongside robots.txt.',
    'content' => '<!-- wp:paragraph {"className":"avr-eyebrow"} -->
<p class="avr-eyebrow">AI Search · 14 February 2026 · 6 min read</p>
<!-- /wp:paragraph -->
<!-- wp:heading {"level":1} -->
<h1 class="wp-block-heading">llms.txt: what it is and how to write one</h1>
<!-- /wp:heading -->
<!-- wp:group {"className":"avr-callout","layout":{"type":"constrained"}} -->
<div class="wp-block-group avr-callout"><!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Quick answer</h3>
<!-- /wp:heading -->
<!-- wp:paragraph -->
<p>llms.txt is a markdown file at your domain root that lists your most useful pages with short descriptions, helping AI systems find authoritative content quickly. It does not control access — robots.txt does that — and it is not yet an official standard, but it is cheap to add and already read by several AI tools.</p>
<!-- /wp:paragraph --></div>
<!-- /wp:group -->
<!-- wp:image {"sizeSlug":"large"} -->
<figure class="wp-block-image size-large"><img src="/images/ai-team-holographic-office.webp" alt="llms.txt: what it is and how to write one"/></figure>
<!-- /wp:image -->
<!-- wp:heading {"level":2,"anchor":"what"} -->
<h2 class="wp-block-heading" id="what">What goes in the file</h2>
<!-- /wp:heading -->
<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">A good llms.txt contains</h3>
<!-- /wp:heading -->
<!-- wp:list -->
<ul class="wp-block-list"><li>An H1 with your brand name and a one-line description of what you do</li><li>A short summary paragraph stating your services, markets and differentiators</li><li>Grouped links to your core service, pricing, documentation and FAQ pages</li><li>A one-line description for each link explaining what question it answers</li><li>Contact details and a canonical statement of your business facts</li></ul>
<!-- /wp:list -->
<!-- wp:heading {"level":2,"anchor":"vs-robots"} -->
<h2 class="wp-block-heading" id="vs-robots">llms.txt vs robots.txt vs sitemap.xml</h2>
<!-- /wp:heading -->
<!-- wp:table {"className":"is-style-stripes"} -->
<figure class="wp-block-table is-style-stripes"><table><thead><tr><th>File</th><th>Purpose</th><th>Who reads it</th></tr></thead><tbody><tr><td>robots.txt</td><td>Grants or blocks crawler access</td><td>All crawlers, enforced by convention</td></tr><tr><td>sitemap.xml</td><td>Lists every indexable URL</td><td>Search engine crawlers</td></tr><tr><td>llms.txt</td><td>Curates the best pages with context</td><td>AI tools that choose to support it</td></tr></tbody></table></figure>
<!-- /wp:table -->
<!-- wp:heading {"level":2,"anchor":"caveat"} -->
<h2 class="wp-block-heading" id="caveat">Honest caveats</h2>
<!-- /wp:heading -->
<!-- wp:group {"className":"avr-callout","layout":{"type":"constrained"}} -->
<div class="wp-block-group avr-callout"><!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Do not over-invest</h3>
<!-- /wp:heading -->
<!-- wp:paragraph -->
<p>llms.txt takes 30 minutes and may help. It is not a substitute for crawlable content, schema or authority. If you only have time for one thing, add answer-first summaries to your top 20 pages instead.</p>
<!-- /wp:paragraph --></div>
<!-- /wp:group -->
<!-- wp:heading {"level":2,"anchor":"faqs"} -->
<h2 class="wp-block-heading" id="faqs">Frequently asked questions</h2>
<!-- /wp:heading -->
<!-- wp:details -->
<details class="wp-block-details"><summary>Is llms.txt an official standard?</summary><!-- wp:paragraph -->
<p>No. It is a community proposal that some AI tools support. It is low-cost to add but carries no guarantee of use.</p>
<!-- /wp:paragraph --></details>
<!-- /wp:details -->
<!-- wp:details -->
<details class="wp-block-details"><summary>Where do I put llms.txt?</summary><!-- wp:paragraph -->
<p>At the root of your domain, so it is reachable at yourdomain.com/llms.txt, served as plain text or markdown.</p>
<!-- /wp:paragraph --></details>
<!-- /wp:details -->
<!-- wp:details -->
<details class="wp-block-details"><summary>Does llms.txt block AI training?</summary><!-- wp:paragraph -->
<p>No. Access control belongs in robots.txt via user-agent directives such as GPTBot and Google-Extended.</p>
<!-- /wp:paragraph --></details>
<!-- /wp:details -->
<!-- wp:details -->
<details class="wp-block-details"><summary>How long should llms.txt be?</summary><!-- wp:paragraph -->
<p>Usually under 100 lines. Curate your best pages rather than duplicating your sitemap.</p>
<!-- /wp:paragraph --></details>
<!-- /wp:details -->
<!-- wp:details -->
<details class="wp-block-details"><summary>Should I keep it updated?</summary><!-- wp:paragraph -->
<p>Yes — review quarterly and whenever you launch a major service page, so the file reflects your current best content.</p>
<!-- /wp:paragraph --></details>
<!-- /wp:details -->
<!-- wp:heading {"level":2} -->
<h2 class="wp-block-heading">Related services and resources</h2>
<!-- /wp:heading -->
<!-- wp:list -->
<ul class="wp-block-list"><li><a href="/blog">All articles</a></li><li><a href="/ai-seo">AI SEO services</a></li><li><a href="/seo-services">SEO services</a></li><li><a href="/pricing">Pricing</a></li></ul>
<!-- /wp:list -->
<!-- wp:group {"className":"avr-cta","layout":{"type":"constrained"}} -->
