  array(
    'slug' => 'technical-seo-checklist',
    'path' => '/blog/technical-seo-checklist',
    'parent' => 'blog',
    'type' => 'post',
    'title' => 'Technical SEO Checklist for 2026 (52 Points)',
    'description' => 'A working technical SEO checklist covering crawling, indexation, Core Web Vitals, structured data, JavaScript rendering and AI crawler access — in the order we actually run them.',
    'content' => '<!-- wp:paragraph {"className":"avr-eyebrow"} -->
<p class="avr-eyebrow">SEO · 5 January 2026 · 11 min read</p>
<!-- /wp:paragraph -->
<!-- wp:heading {"level":1} -->
<h1 class="wp-block-heading">The technical SEO checklist we run on every audit</h1>
<!-- /wp:heading -->
<!-- wp:group {"className":"avr-callout","layout":{"type":"constrained"}} -->
<div class="wp-block-group avr-callout"><!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Quick answer</h3>
<!-- /wp:heading -->
<!-- wp:paragraph -->
<p>A technical SEO audit should run in this order: crawl access, indexation, site architecture, Core Web Vitals, rendering, structured data, internationalisation and AI crawler access. Fixing crawl and indexation first is what makes every later fix measurable, because Google must be able to see the change.</p>
<!-- /wp:paragraph --></div>
<!-- /wp:group -->
<!-- wp:image {"sizeSlug":"large"} -->
<figure class="wp-block-image size-large"><img src="/images/seo-search-engine.webp" alt="The technical SEO checklist we run on every audit"/></figure>
<!-- /wp:image -->
<!-- wp:heading {"level":2,"anchor":"crawl"} -->
<h2 class="wp-block-heading" id="crawl">1. Crawl and access</h2>
<!-- /wp:heading -->
<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Check</h3>
<!-- /wp:heading -->
<!-- wp:list -->
<ul class="wp-block-list"><li>robots.txt does not block CSS, JS or important sections</li><li>No accidental noindex on templates or staging leftovers</li><li>Server returns correct status codes — no soft 404s or 200 error pages</li><li>Redirect chains resolved to a single hop</li><li>Crawl budget is not consumed by faceted or parameter URLs</li></ul>
<!-- /wp:list -->
<!-- wp:heading {"level":2,"anchor":"index"} -->
<h2 class="wp-block-heading" id="index">2. Indexation and duplication</h2>
<!-- /wp:heading -->
<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Check</h3>
<!-- /wp:heading -->
<!-- wp:list -->
<ul class="wp-block-list"><li>Search Console coverage report has no unexplained exclusions</li><li>Canonical tags are self-referencing and consistent with internal links</li><li>Pagination is crawlable and not blocked by infinite scroll</li><li>Thin, near-duplicate pages are consolidated or improved</li><li>XML sitemaps are split by template and contain only indexable URLs</li></ul>
<!-- /wp:list -->
<!-- wp:heading {"level":2,"anchor":"speed"} -->
<h2 class="wp-block-heading" id="speed">3. Core Web Vitals</h2>
<!-- /wp:heading -->
<!-- wp:table {"className":"is-style-stripes"} -->
<figure class="wp-block-table is-style-stripes"><table><thead><tr><th>Metric</th><th>Target</th><th>Most common fix</th></tr></thead><tbody><tr><td>LCP</td><td>&lt; 2.5s</td><td>Preload hero image, cut render-blocking CSS</td></tr><tr><td>INP</td><td>&lt; 200ms</td><td>Break long JS tasks, defer third-party scripts</td></tr><tr><td>CLS</td><td>&lt; 0.1</td><td>Set width and height on images and ad slots</td></tr><tr><td>TTFB</td><td>&lt; 0.8s</td><td>Server caching, CDN, reduce redirect hops</td></tr></tbody></table></figure>
<!-- /wp:table -->
<!-- wp:heading {"level":2,"anchor":"ai"} -->
<h2 class="wp-block-heading" id="ai">4. Structured data and AI access</h2>
<!-- /wp:heading -->
<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Check</h3>
<!-- /wp:heading -->
<!-- wp:list -->
<ul class="wp-block-list"><li>Organization, WebSite and Breadcrumb schema sitewide</li><li>Page-type schema — Product, Article, FAQPage, LocalBusiness — where accurate</li><li>No schema for content invisible to users</li><li>AI user agents explicitly allowed if you want AI visibility</li><li>Key facts rendered server-side, not injected by client-only JavaScript</li></ul>
<!-- /wp:list -->
<!-- wp:heading {"level":2,"anchor":"faqs"} -->
<h2 class="wp-block-heading" id="faqs">Frequently asked questions</h2>
<!-- /wp:heading -->
<!-- wp:details -->
<details class="wp-block-details"><summary>How often should I run a technical audit?</summary><!-- wp:paragraph -->
<p>A full audit twice a year, a light crawl monthly, and always immediately after a redesign, migration or CMS change.</p>
<!-- /wp:paragraph --></details>
<!-- /wp:details -->
<!-- wp:details -->
<details class="wp-block-details"><summary>What is the single most damaging technical issue?</summary><!-- wp:paragraph -->
<p>Blocking or noindexing pages that should rank. Nothing else matters if the page cannot be crawled or indexed.</p>
<!-- /wp:paragraph --></details>
<!-- /wp:details -->
<!-- wp:details -->
<details class="wp-block-details"><summary>Do Core Web Vitals affect rankings?</summary><!-- wp:paragraph -->
<p>They are a modest ranking signal, but their bigger effect is on conversions and on whether crawlers and AI retrievers finish fetching your pages.</p>
<!-- /wp:paragraph --></details>
<!-- /wp:details -->
<!-- wp:details -->
<details class="wp-block-details"><summary>Is JavaScript bad for SEO?</summary><!-- wp:paragraph -->
<p>Not inherently, but client-only rendering delays indexing and can hide content from AI retrievers. Server-render your critical content.</p>
<!-- /wp:paragraph --></details>
<!-- /wp:details -->
<!-- wp:details -->
<details class="wp-block-details"><summary>Can I do this checklist myself?</summary><!-- wp:paragraph -->
<p>Most of it, with Search Console and a crawler like Screaming Frog. Log-file analysis and rendering debugging usually need specialist help.</p>
<!-- /wp:paragraph --></details>
<!-- /wp:details -->
<!-- wp:heading {"level":2} -->
<h2 class="wp-block-heading">Related services and resources</h2>
<!-- /wp:heading -->
<!-- wp:list -->
<ul class="wp-block-list"><li><a href="/blog">All articles</a></li><li><a href="/ai-seo">AI SEO services</a></li><li><a href="/seo-services">SEO services</a></li><li><a href="/pricing">Pricing</a></li></ul>
<!-- /wp:list -->
<!-- wp:group {"className":"avr-cta","layout":{"type":"constrained"}} -->
<div class="wp-block-group avr-cta"><!-- wp:heading -->
<h2 class="wp-block-heading">Ready to grow your business?</h2>
<!-- /wp:heading -->
<!-- wp:paragraph -->
<p>Tell us about your goals and we will recommend the most practical next steps for your website, visibility, and lead generation.</p>
<!-- /wp:paragraph -->
<!-- wp:buttons -->
<div class="wp-block-buttons"><!-- wp:button -->
<div class="wp-block-button"><a class="wp-block-button__link wp-element-button" href="/contact">Request a digital audit</a></div>
<!-- /wp:button --></div>
<!-- /wp:buttons --></div>
<!-- /wp:group -->
