  array(
    'slug' => 'core-web-vitals-fixes',
    'path' => '/blog/core-web-vitals-fixes',
    'parent' => 'blog',
    'type' => 'post',
    'title' => 'Core Web Vitals: The Fixes That Actually Move the Needle',
    'description' => 'Practical LCP, INP and CLS fixes ranked by impact per hour of work, based on the sites we rebuild — plus how to avoid chasing lab scores that field data ignores.',
    'content' => '<!-- wp:paragraph {"className":"avr-eyebrow"} -->
<p class="avr-eyebrow">Web Design · 25 February 2026 · 8 min read</p>
<!-- /wp:paragraph -->
<!-- wp:heading {"level":1} -->
<h1 class="wp-block-heading">Core Web Vitals fixes that actually change your scores</h1>
<!-- /wp:heading -->
<!-- wp:group {"className":"avr-callout","layout":{"type":"constrained"}} -->
<div class="wp-block-group avr-callout"><!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Quick answer</h3>
<!-- /wp:heading -->
<!-- wp:paragraph -->
<p>The highest-impact Core Web Vitals fixes are: preload and properly size the LCP image, remove render-blocking CSS and fonts, defer or remove third-party scripts, set explicit dimensions on all media, and break long JavaScript tasks. Field data from real users, not Lighthouse lab scores, is what Google uses.</p>
<!-- /wp:paragraph --></div>
<!-- /wp:group -->
<!-- wp:image {"sizeSlug":"large"} -->
<figure class="wp-block-image size-large"><img src="/images/web-developer-isometric.webp" alt="Core Web Vitals fixes that actually change your scores"/></figure>
<!-- /wp:image -->
<!-- wp:heading {"level":2,"anchor":"lcp"} -->
<h2 class="wp-block-heading" id="lcp">LCP: usually one image and one stylesheet</h2>
<!-- /wp:heading -->
<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">In order of impact</h3>
<!-- /wp:heading -->
<!-- wp:list -->
<ul class="wp-block-list"><li>Serve the hero image in modern format at the exact rendered size</li><li>Preload it and never lazy-load the above-the-fold image</li><li>Inline critical CSS, defer the rest</li><li>Self-host fonts with font-display: swap and preload the primary weight</li><li>Cut TTFB with edge caching before optimising anything on the page</li></ul>
<!-- /wp:list -->
<!-- wp:heading {"level":2,"anchor":"inp"} -->
<h2 class="wp-block-heading" id="inp">INP: your JavaScript is doing too much</h2>
<!-- /wp:heading -->
<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Fixes</h3>
<!-- /wp:heading -->
<!-- wp:list -->
<ul class="wp-block-list"><li>Audit third-party tags — chat widgets and heatmaps are frequent offenders</li><li>Split long tasks and yield to the main thread</li><li>Debounce expensive handlers on scroll and input</li><li>Hydrate interactive components only when visible</li></ul>
<!-- /wp:list -->
<!-- wp:heading {"level":2,"anchor":"cls"} -->
<h2 class="wp-block-heading" id="cls">CLS: reserve the space</h2>
<!-- /wp:heading -->
<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Fixes</h3>
<!-- /wp:heading -->
<!-- wp:list -->
<ul class="wp-block-list"><li>Width and height attributes on every image and video</li><li>Reserved containers for ads, embeds and cookie banners</li><li>Avoid injecting banners above existing content after load</li><li>Preload fonts to prevent late swaps shifting text blocks</li></ul>
<!-- /wp:list -->
<!-- wp:heading {"level":2,"anchor":"measure"} -->
<h2 class="wp-block-heading" id="measure">Measure the right thing</h2>
<!-- /wp:heading -->
<!-- wp:group {"className":"avr-callout","layout":{"type":"constrained"}} -->
<div class="wp-block-group avr-callout"><!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Field over lab</h3>
<!-- /wp:heading -->
<!-- wp:paragraph -->
<p>Chrome User Experience Report field data drives the Core Web Vitals assessment. A perfect Lighthouse score on your laptop means little if real users on 4G mid-range Android phones see a 4s LCP.</p>
<!-- /wp:paragraph --></div>
<!-- /wp:group -->
<!-- wp:heading {"level":2,"anchor":"faqs"} -->
<h2 class="wp-block-heading" id="faqs">Frequently asked questions</h2>
<!-- /wp:heading -->
<!-- wp:details -->
<details class="wp-block-details"><summary>Do Core Web Vitals affect rankings much?</summary><!-- wp:paragraph -->
<p>They are a tiebreaker rather than a primary signal, but the conversion and crawl-efficiency gains usually justify the work by themselves.</p>
<!-- /wp:paragraph --></details>
<!-- /wp:details -->
<!-- wp:details -->
<details class="wp-block-details"><summary>What is a good LCP?</summary><!-- wp:paragraph -->
<p>Under 2.5 seconds for 75% of real users. Under 2 seconds is a safer target on mobile networks.</p>
<!-- /wp:paragraph --></details>
<!-- /wp:details -->
<!-- wp:details -->
<details class="wp-block-details"><summary>Why is my Lighthouse score good but Search Console says failing?</summary><!-- wp:paragraph -->
<p>Lighthouse is a lab simulation on your device; Search Console reports real-user field data across devices and networks.</p>
<!-- /wp:paragraph --></details>
<!-- /wp:details -->
<!-- wp:details -->
<details class="wp-block-details"><summary>Does a page builder ruin Core Web Vitals?</summary><!-- wp:paragraph -->
<p>Heavy builders make good scores harder but not impossible — trimming unused modules, scripts and fonts usually recovers most of the gap.</p>
<!-- /wp:paragraph --></details>
<!-- /wp:details -->
<!-- wp:details -->
<details class="wp-block-details"><summary>How long until improvements show in Search Console?</summary><!-- wp:paragraph -->
<p>Field data updates on a 28-day rolling window, so allow roughly a month after deployment for the report to reflect fixes.</p>
<!-- /wp:paragraph --></details>
<!-- /wp:details -->
<!-- wp:heading {"level":2} -->
<h2 class="wp-block-heading">Related services and resources</h2>
<!-- /wp:heading -->
<!-- wp:list -->
<ul class="wp-block-list"><li><a href="/blog">All articles</a></li><li><a href="/ai-seo">AI SEO services</a></li><li><a href="/seo-services">SEO services</a></li><li><a href="/pricing">Pricing</a></li></ul>
<!-- /wp:list -->
<!-- wp:group {"className":"avr-cta","layout":{"type":"constrained"}} -->
