  array(
    'slug' => 'international-seo-hreflang',
    'path' => '/blog/international-seo-hreflang',
    'parent' => 'blog',
    'type' => 'post',
    'title' => 'International SEO: Getting Hreflang Right the First Time',
    'description' => 'Domain structure, hreflang implementation, currency and content localisation for brands expanding from India into the US, UK, UAE and Europe.',
    'content' => '<!-- wp:paragraph {"className":"avr-eyebrow"} -->
<p class="avr-eyebrow">SEO · 18 March 2026 · 8 min read</p>
<!-- /wp:paragraph -->
<!-- wp:heading {"level":1} -->
<h1 class="wp-block-heading">International SEO and hreflang without the headaches</h1>
<!-- /wp:heading -->
<!-- wp:group {"className":"avr-callout","layout":{"type":"constrained"}} -->
<div class="wp-block-group avr-callout"><!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Quick answer</h3>
<!-- /wp:heading -->
<!-- wp:paragraph -->
<p>For international SEO, choose subdirectories over ccTLDs unless you have local entities, implement bidirectional hreflang with self-referencing tags and an x-default, localise currency, spelling and examples rather than translating literally, and build local links in each target market.</p>
<!-- /wp:paragraph --></div>
<!-- /wp:group -->
<!-- wp:image {"sizeSlug":"large"} -->
<figure class="wp-block-image size-large"><img src="/images/marketing-bridge-illustration.webp" alt="International SEO and hreflang without the headaches"/></figure>
<!-- /wp:image -->
<!-- wp:heading {"level":2,"anchor":"structure"} -->
<h2 class="wp-block-heading" id="structure">Choosing a structure</h2>
<!-- /wp:heading -->
<!-- wp:table {"className":"is-style-stripes"} -->
<figure class="wp-block-table is-style-stripes"><table><thead><tr><th>Structure</th><th>Pros</th><th>Cons</th></tr></thead><tbody><tr><td>example.com/uk/</td><td>Consolidated authority, cheapest to run</td><td>Weaker local signal than a ccTLD</td></tr><tr><td>uk.example.com</td><td>Clear separation, flexible hosting</td><td>Authority splits across subdomains</td></tr><tr><td>example.co.uk</td><td>Strongest local trust signal</td><td>Expensive, slow to build authority per domain</td></tr></tbody></table></figure>
<!-- /wp:table -->
<!-- wp:heading {"level":2,"anchor":"hreflang"} -->
<h2 class="wp-block-heading" id="hreflang">Hreflang rules that prevent errors</h2>
<!-- /wp:heading -->
<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Get these right</h3>
<!-- /wp:heading -->
<!-- wp:list -->
<ul class="wp-block-list"><li>Every page references itself plus every alternate — links must be bidirectional</li><li>Use language-region codes correctly: en-GB, en-AE, en-US, not uk or uae</li><li>Include an x-default for the global or language-selector page</li><li>Keep canonical tags self-referencing; never canonicalise across locales</li><li>Deliver hreflang consistently in HTML head or XML sitemap, not both partially</li></ul>
<!-- /wp:list -->
<!-- wp:heading {"level":2,"anchor":"localise"} -->
<h2 class="wp-block-heading" id="localise">Localisation beyond translation</h2>
<!-- /wp:heading -->
<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">What to adapt</h3>
<!-- /wp:heading -->
<!-- wp:list -->
<ul class="wp-block-list"><li>Currency, tax display and payment methods buyers expect locally</li><li>Spelling and idiom — optimise, optimise vs optimize matters for query match</li><li>Local proof: case studies, testimonials and phone numbers from that market</li><li>Search behaviour: UAE audiences often search in English with Arabic brand terms</li></ul>
<!-- /wp:list -->
<!-- wp:heading {"level":2,"anchor":"faqs"} -->
<h2 class="wp-block-heading" id="faqs">Frequently asked questions</h2>
<!-- /wp:heading -->
<!-- wp:details -->
<details class="wp-block-details"><summary>Do I need separate sites per country?</summary><!-- wp:paragraph -->
<p>Rarely. Subdirectories with hreflang serve most brands better because they consolidate authority and are cheaper to maintain.</p>
<!-- /wp:paragraph --></details>
<!-- /wp:details -->
<!-- wp:details -->
<details class="wp-block-details"><summary>Is hreflang a ranking factor?</summary><!-- wp:paragraph -->
<p>No, it is a targeting signal. It tells Google which version to show which audience, preventing wrong-locale results and duplication issues.</p>
<!-- /wp:paragraph --></details>
<!-- /wp:details -->
<!-- wp:details -->
<details class="wp-block-details"><summary>Can I use automatic translation?</summary><!-- wp:paragraph -->
<p>Only as a first draft. Machine translation without local review produces awkward phrasing that fails to match real local search queries.</p>
<!-- /wp:paragraph --></details>
<!-- /wp:details -->
<!-- wp:details -->
<details class="wp-block-details"><summary>Should I redirect users by IP?</summary><!-- wp:paragraph -->
<p>No. Auto-redirects can block crawlers from other locales. Offer a dismissible suggestion banner instead.</p>
<!-- /wp:paragraph --></details>
<!-- /wp:details -->
<!-- wp:details -->
<details class="wp-block-details"><summary>How long does international SEO take?</summary><!-- wp:paragraph -->
<p>Expect 4-8 months per new market, since local authority and links must be built even when your home domain is strong.</p>
<!-- /wp:paragraph --></details>
<!-- /wp:details -->
<!-- wp:heading {"level":2} -->
<h2 class="wp-block-heading">Related services and resources</h2>
<!-- /wp:heading -->
<!-- wp:list -->
<ul class="wp-block-list"><li><a href="/blog">All articles</a></li><li><a href="/ai-seo">AI SEO services</a></li><li><a href="/seo-services">SEO services</a></li><li><a href="/pricing">Pricing</a></li></ul>
<!-- /wp:list -->
<!-- wp:group {"className":"avr-cta","layout":{"type":"constrained"}} -->
<div class="wp-block-group avr-cta"><!-- wp:heading -->
<h2 class="wp-block-heading">Ready to grow your business?</h2>
<!-- /wp:heading -->
<!-- wp:paragraph -->
<p>Tell us about your goals and we will recommend the most practical next steps for your website, visibility, and lead generation.</p>
<!-- /wp:paragraph -->
<!-- wp:buttons -->
<div class="wp-block-buttons"><!-- wp:button -->
<div class="wp-block-button"><a class="wp-block-button__link wp-element-button" href="/contact">Request a digital audit</a></div>
<!-- /wp:button --></div>
