  array(
    'slug' => 'small-business-seo-budget',
    'path' => '/blog/small-business-seo-budget',
    'parent' => 'blog',
    'type' => 'post',
    'title' => 'SEO for Small Business Websites: Where to Start | AVR Web',
    'description' => 'New to SEO? Learn what small business owners should fix first on their website to get found on Google, from page titles to local listings and more.',
    'content' => '<!-- wp:paragraph {"className":"avr-eyebrow"} -->
<p class="avr-eyebrow">SEO · 2 April 2026 · 8 min read</p>
<!-- /wp:paragraph -->
<!-- wp:heading {"level":1} -->
<h1 class="wp-block-heading">SEO on a small budget: the first 90 days with $100 a month</h1>
<!-- /wp:heading -->
<!-- wp:group {"className":"avr-callout","layout":{"type":"constrained"}} -->
<div class="wp-block-group avr-callout"><!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Quick answer</h3>
<!-- /wp:heading -->
<!-- wp:paragraph -->
<p>With $100/month, spend month one on technical fixes and Google Business Profile, month two on your three highest-intent service pages with answer-first content and schema, and month three on reviews, local citations and two supporting articles. Prioritise conversion-ready pages over blog volume.</p>
<!-- /wp:paragraph --></div>
<!-- /wp:group -->
<!-- wp:image {"sizeSlug":"large"} -->
<figure class="wp-block-image size-large"><img src="/images/freelancer-laptop.webp" alt="SEO on a small budget: the first 90 days with $100 a month"/></figure>
<!-- /wp:image -->
<!-- wp:heading {"level":2,"anchor":"month1"} -->
<h2 class="wp-block-heading" id="month1">Month 1: foundations</h2>
<!-- /wp:heading -->
<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Deliverables</h3>
<!-- /wp:heading -->
<!-- wp:list -->
<ul class="wp-block-list"><li>Fix crawl, indexation and mobile usability blockers</li><li>Claim and fully populate the Google Business Profile</li><li>Install GA4 and Search Console with conversion tracking</li><li>Write titles and meta descriptions for the top 10 pages</li><li>Add Organization and LocalBusiness schema</li></ul>
<!-- /wp:list -->
<!-- wp:heading {"level":2,"anchor":"month2"} -->
<h2 class="wp-block-heading" id="month2">Month 2: money pages</h2>
<!-- /wp:heading -->
<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Deliverables</h3>
<!-- /wp:heading -->
<!-- wp:list -->
<ul class="wp-block-list"><li>Rewrite your three highest-intent service pages with a 50-word answer block</li><li>Add pricing guidance — the single most requested missing information</li><li>Add 8-10 FAQs per page with FAQPage schema</li><li>Internal links from the homepage and blog into those pages</li></ul>
<!-- /wp:list -->
<!-- wp:heading {"level":2,"anchor":"month3"} -->
<h2 class="wp-block-heading" id="month3">Month 3: proof and reach</h2>
<!-- /wp:heading -->
<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Deliverables</h3>
<!-- /wp:heading -->
<!-- wp:list -->
<ul class="wp-block-list"><li>Review generation flow via SMS or WhatsApp after each job</li><li>Ten accurate local citations on the directories that matter in your market</li><li>Two supporting articles answering the questions customers ask before buying</li><li>First measurement review — rankings, calls, forms, and what to double down on</li></ul>
<!-- /wp:list -->
<!-- wp:heading {"level":2,"anchor":"skip"} -->
<h2 class="wp-block-heading" id="skip">What to skip at this budget</h2>
<!-- /wp:heading -->
<!-- wp:group {"className":"avr-callout","layout":{"type":"constrained"}} -->
<div class="wp-block-group avr-callout"><!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Not yet</h3>
<!-- /wp:heading -->
<!-- wp:paragraph -->
<p>Skip paid link packages, daily blogging, video production and enterprise tools. At $100/month, precision on a handful of pages beats spreading thin across a content calendar.</p>
<!-- /wp:paragraph --></div>
<!-- /wp:group -->
<!-- wp:heading {"level":2,"anchor":"faqs"} -->
<h2 class="wp-block-heading" id="faqs">Frequently asked questions</h2>
<!-- /wp:heading -->
<!-- wp:details -->
<details class="wp-block-details"><summary>Is $100 a month enough for SEO?</summary><!-- wp:paragraph -->
<p>For a single-location local business, yes — it funds focused monthly work. For competitive national or e-commerce terms it is not; expect $300-600/month there.</p>
<!-- /wp:paragraph --></details>
<!-- /wp:details -->
<!-- wp:details -->
<details class="wp-block-details"><summary>What should I do myself to save money?</summary><!-- wp:paragraph -->
<p>Collect reviews, supply photos, answer our subject-matter questions and publish updates. Those cost you time and save agency hours.</p>
<!-- /wp:paragraph --></details>
<!-- /wp:details -->
<!-- wp:details -->
<details class="wp-block-details"><summary>When will I see leads?</summary><!-- wp:paragraph -->
<p>Local businesses commonly see the first additional calls within 6-10 weeks, mostly from Business Profile and map-pack improvements.</p>
<!-- /wp:paragraph --></details>
<!-- /wp:details -->
<!-- wp:details -->
<details class="wp-block-details"><summary>Should I buy backlinks with a small budget?</summary><!-- wp:paragraph -->
<p>No. At this budget, cheap links are the fastest way to waste money and risk penalties. Reviews and citations return more.</p>
<!-- /wp:paragraph --></details>
<!-- /wp:details -->
<!-- wp:details -->
<details class="wp-block-details"><summary>Can I pause and resume later?</summary><!-- wp:paragraph -->
<p>You can, and rankings usually hold for a while, but competitors keep publishing — restarting after long gaps costs more than staying consistent.</p>
<!-- /wp:paragraph --></details>
<!-- /wp:details -->
<!-- wp:heading {"level":2} -->
<h2 class="wp-block-heading">Related services and resources</h2>
<!-- /wp:heading -->
<!-- wp:list -->
<ul class="wp-block-list"><li><a href="/blog">All articles</a></li><li><a href="/ai-seo">AI SEO services</a></li><li><a href="/seo-services">SEO services</a></li><li><a href="/pricing">Pricing</a></li></ul>
<!-- /wp:list -->
<!-- wp:group {"className":"avr-cta","layout":{"type":"constrained"}} -->
<div class="wp-block-group avr-cta"><!-- wp:heading -->
<h2 class="wp-block-heading">Ready to grow your business?</h2>
<!-- /wp:heading -->
<!-- wp:paragraph -->
<p>Tell us about your goals and we will recommend the most practical next steps for your website, visibility, and lead generation.</p>
